// Mutex (Mutual Exclusion) and RAII Locking
std::mutex data_mtx;
int shared_data = 0;

void access_critical_section() {
    // Acquire lock upon scope entry
    std::lock_guard<std::mutex> lock(data_mtx);
    shared_data += 1;
    // Release lock upon scope exit (RAII)
}

// Thread Management (Creation and Joining)
void worker_task(int id) { /* ... concurrent work ... */ }

std::thread t1(worker_task, 1);
std::thread t2([]{ /* lambda job */ });

t1.join(); // Wait for t1 to complete
t2.detach(); // Let t2 run independently

// Condition Variable (Wait/Notify for Synchronization)
std::mutex m;
std::condition_variable cv;
bool data_ready = false;

void waiter() {
    std::unique_lock<std::mutex> lock(m);
    // Wait until condition is true
    cv.wait(lock, []{ return data_ready; });
    // Process data
}

void notifier() {
    {
        std::lock_guard<std::mutex> lock(m);
        data_ready = true;
    }
    cv.notify_all(); // Wake waiting threads
}

// Atomic Operations (Lock-Free Synchronization)
std::atomic<long> high_throughput_counter = 0;

void safe_increment() {
    high_throughput_counter++; // Atomic update
}

bool compare_exchange(long old_val, long new_val) {
    // CAS (Compare and Swap)
    return high_throughput_counter.compare_exchange_strong(old_val, new_val);
}
